def migrate(cr, version):
    env = api.Environment(cr, SUPERUSER_ID, {})
    for xml_id, digests in SHIPPED_DIGESTS.items():
        definition = env.ref('blue_wcs_extension.' + xml_id, raise_if_not_found=False)
        if not definition:
            continue
        values = {'cloud_managed': True, 'active': False}
        for name, expected in digests.items():
            if hashlib.sha256((definition[name] or '').encode()).hexdigest() == expected:
                values[name] = False
        # Administrator-edited legacy template content is archived, never used as AI fallback.
        definition.write(values)
